#!/usr/bin/env python3
"""Writes library/src/binary/exponent_field_rows_wbtest.mbt from `exponent_field_rows.py`
(exponent fields of 2^63 - 1 .. 40 digits for `from_string_ctx` and `from_hex_ctx`).

    python3 tools/generate_exponent_field_rows.py [--check] && moon fmt
"""

from __future__ import annotations

import argparse
import sys
from pathlib import Path

import exponent_field_rows

ROOT = Path(__file__).resolve().parents[1]
OUTPUT = ROOT / "library/src/binary/exponent_field_rows_wbtest.mbt"


def render(rows) -> str:
    lines = [
        "// Generated by tools/generate_exponent_field_rows.py; do not edit.",
        "// Exponent fields of 2^63 - 1 and more, exact arithmetic and the range rule of IEEE 754-2019 7.4, 7.5:",
        "// (radix, text, format, precision, e_min, e_max, rounding, tininess, expected, flags).",
        "",
        "///|",
        "fn exponent_field_rows() -> Array[(Int32, String, String, Int32, Int32, Int32, String, String, String, String)] {",
        "  [",
    ]
    for radix, text, name, p, emin, emax, mode, tininess, expected, flags in rows:
        lines.append(f'    ({radix}, "{text}", "{name}", {p}, {emin}, {emax}, "{mode}", "{tininess}", "{expected}", "{flags}"),')
    lines += ["  ]", "}", ""]
    return "\n".join(lines)


def main(argv=None) -> int:
    parser = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    parser.add_argument("--check", action="store_true")
    args = parser.parse_args(argv)
    text = render(exponent_field_rows.all_rows())
    if args.check:
        squeeze = lambda value: "".join(value.split()).replace(",)", ")").replace(",]", "]")
        ok = OUTPUT.is_file() and squeeze(OUTPUT.read_text(encoding="utf-8")) == squeeze(text)
        if not ok:
            print(f"stale: {OUTPUT}", file=sys.stderr)
        return 0 if ok else 1
    OUTPUT.write_text(text, encoding="utf-8")
    print(f"{OUTPUT}: {len(exponent_field_rows.all_rows())} rows")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
